def route(ticket, d):
    team = d["team"]
    if team.abstain or team.choice == "none_of_these":
        return review_queue.add(ticket, decision_id=d.id)

    queue = queues[team.choice]
    priority = "p1" if d["urgency"].score >= 2.5 else "p2" if d["urgency"].score >= 1.5 else "p3"
    queue.add(ticket, priority=priority, decision_id=d.id)

    if d["churn_risk"].noul >= 0.8:
        notify_account_manager(ticket)
